{
  "research_concepts": [
    "defensive suppression",
    "counter strategy",
    "recommended offensive mix after suppression",
    "playoff series winning",
    "adherence to game plan"
  ],
  "methodological_questions": [
    "how to define suppression-conditional recommended mix without lookahead bias",
    "how to measure adherence at the series level",
    "adequate power with 54 series",
    "confounding by overall team strength",
    "whether the recommended mix generalises from regular season to playoffs",
    "avoiding in-sample optimisation of the recommendation"
  ],
  "historical_evidence": [
    {
      "id": "FAM:SF-APPM-001",
      "status_as_recorded": "supported",
      "finding": "In holdout regular-season games, teams whose play-type mix is closer to the model's recommended mix score more efficiently; strength-controlled gap +3.27 ORtg."
    },
    {
      "id": "FAM:SF-APPM-054",
      "status_as_recorded": "rejected",
      "finding": "Pivoting to a listed counter after suppression does not sustain higher PPP in playoff matchups; 10/12 pairs within 0.10 of non-pivot, two pairs with enough signal are PIVOT_LOSES."
    },
    {
      "id": "FAM:SF-APPS-023",
      "status_as_recorded": "rejected",
      "finding": "Non-CUT BEST counters do not beat a feasibility-weighted league mix; the headline effect is driven entirely by CUT; H2H non-CUT gap +0.001, p=0.3277."
    },
    {
      "id": "FAM:SF-APPM-055",
      "status_as_recorded": "inconclusive",
      "finding": "L1 best counter after DRIVE is CUT, but L2 MIA disagrees (best=PNR); L3 samples very small; stability of counter rankings uncertain."
    },
    {
      "id": "FAM:SF-APPS-017",
      "status_as_recorded": "not a hypothesis test",
      "finding": "Observed play-type mix frequently deviates from the recommended plan; average |delta| 4.5–24.0 pp on leverage buckets; in 4 of 8 sides the best-matching opener was #3, not rank-1."
    },
    {
      "id": "FAM:SF08",
      "status_as_recorded": "not a hypothesis test",
      "finding": "Teams' post-trigger BEST vs AVOID share varies widely (BOS 15.7% to HOU 2.5%); win% is not cleanly tied to BEST share."
    },
    {
      "id": "FAM:SF-APPA-005",
      "status_as_recorded": "untestable",
      "finding": "Inferred defensive scheme changes are observed in nearly all series, but near-uniform transition matrices are consistent with label noise, making it impossible to separate real adjustment from offence execution."
    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-APPM-054",
      "what_failed": "testing whether pivoting to the listed counter after suppression yields higher playoff PPP",
      "why": "adequately powered null result; most pair deltas <0.10, and the two pairs with enough signal showed the pivot losing to non-pivot."
    },
    {
      "id": "FAM:SF-APPS-023",
      "what_failed": "testing whether matchup-specific non-CUT BEST counters outperform a league mix",
      "why": "adequately powered null (p=0.17 overall, p=0.33 in L3); effect is confined to CUT, limiting the generalisability of the recommended mix."
    },
    {
      "id": "FAM:SF-APPA-005",
      "what_failed": "inferring defensive scheme changes from play-type labels",
      "why": "label/classification error; inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with noise."
    }
  ],
  "evidence_establishes": [
    "In regular-season holdout games, aligning the offence's play-type mix with the suppression-conditional recommended mix is associated with a small but systematic efficiency gain (+3.3 ORtg after strength control).",
    "In playoff matchups, the prescribed counters (e.g., PNR after a suppression) do not reliably sustain a higher PPP, and many pairs show no advantage; the only robust signal comes from the CUT counter.",
    "Teams' observed mix often deviates from the recommendation, and static rank-1 recommendations rarely match the best observed mix in a given game.",
    "Defensive scheme change is ubiquitous but cannot be reliably measured with inferred labels."
  ],
  "evidence_does_not_establish": [
    "That adhering to the recommended mix actually predicts series victory, rather than just point-level efficiency in regular-season games.",
    "That the small efficiency gain (+3.3 ORtg) is large enough to shift series win probability in a detectable way with 54 series.",
    "That the recommended mix, trained on regular-season data, transfers to playoff conditions where defensive intensity and coaching adjustments differ.",
    "That adherence, as opposed to overall team quality or game-script effects, is causally responsible for any observed outcome."
  ],
  "own_inferences": [
    "The question could be operationalised at the series level: for each series, compute each team's average distance from its recommended mix (the mix being derived from pre-series data only) and test whether the team with the smaller distance wins the series more often than chance.",
    "With 54 series, a one-sample binomial test of the proportion of series won by the more adherent team would require an observed proportion near 0.67 to achieve 80% power (two-sided alpha 0.05). This demands an unrealistically large effect.",
    "A continuous adherence predictor in a logistic regression would likewise be underpowered unless the true effect is very strong.",
    "Given the null playoff-efficiency results in SF-APPM-054 and SF-APPS-023, the prior probability that adherence meaningfully improves playoff scoring – and hence series win probability – is low, further shrinking the effective power."
  ],
  "uncertainties": [
    "Exact translation of the +3.3 ORtg into series win probability is model-dependent and has not been empirically validated in a playoff setting.",
    "Whether a refined recommendation (e.g., restricting to CUT-only, or incorporating game-state leverage) would improve playoff predictive value.",
    "Stability of the regular-season recommendation when the opponent makes systematic defensive adjustments across games within a series.",
    "Measurement noise in play-type classification and in the suppression-trigger detection may attenuate adherence metrics."
  ],
  "historical_effect": {
    "changed_decision": "yes",
    "explanation": "Without the historical evidence, the test would have appeared straightforward: compute adherence, regress on series win. However, SF-APPM-054 and SF-APPS-023 show that the recommended mix does not reliably improve playoff efficiency, which is the mechanistic link to winning. This substantially lowers the prior probability that a series-level effect could be detected, and together with the small sample makes the study unlikely to yield a compelling result."
  },
  "testability": {
    "p_testable": 0.25,
    "blocking_constraints": [
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "Only 54 independent series are available for a binary outcome. A large effect (e.g., adherent team winning >67% of series) would be required for adequate power, which is implausible given the prior evidence of small or null playoff effects."
      },
      {
        "code": "EXPOSURE_SPARSITY",
        "text": "The recommended mix depends on suppression-triggered possessions; rare play-type combinations may have too few events per series to reliably estimate adherence differences between teams."
      }
    ]
  },
  "prior_work": {
    "already_answered": "partly",
    "cited": [
      "FAM:SF-APPM-001",
      "FAM:SF-APPM-054",
      "FAM:SF-APPS-023",
      "FAM:SF-APPM-055",
      "FAM:SF-APPS-017",
      "FAM:SF08",
      "FAM:SF-APPA-005"
    ],
    "summary": "SF-APPM-001 demonstrated that closer adherence predicts higher regular-season efficiency. However, subsequent playoff-focused work (SF-APPM-054, SF-APPS-023) failed to replicate a reliable counter advantage, and no study has tested the direct link to series victory. The positive regular-season finding justifies the conceptual chain, but the playoff nulls undermine the assumption that the recommended mix translates into post-season scoring advantages strong enough to affect series outcomes."
  },
  "risks": [
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "54 series is a small sample for a binary outcome; effect sizes observed at the possession level are modest and likely insufficient to produce a detectable series-level effect."
    },
    {
      "code": "CONFOUNDING",
      "text": "Overall team strength, seed, and matchup quality heavily influence series outcomes and may be correlated with adherence (better teams may be more adherent or vice versa)."
    },
    {
      "code": "RTM_SELECTION",
      "text": "Recommendations built on regular-season suppression data may not reflect the true counter value in playoffs, leading to regression-to-the-mean in the measured adherence-outcome relationship."
    },
    {
      "code": "LEAKAGE_LOOKAHEAD",
      "text": "If the recommended mix is derived from any data within the target series (e.g., the first games of the same series), the test becomes circular. A strict pre-series-only training rule must be enforced."
    },
    {
      "code": "MEASURE_RELIABILITY",
      "text": "The adherence metric (e.g., l1 distance between observed and recommended play-type proportions) aggregates over classifications of play type and suppression triggers that have known noise (see SF-APPA-005)."
    },
    {
      "code": "EXPOSURE_SPARSITY",
      "text": "Many play-type counters are rare per series, making team-level adherence estimates unstable and vulnerable to a few outlier possessions."
    }
  ],
  "predicted_outcome": {
    "supported": 0.10,
    "rejected": 0.60,
    "untestable": 0.20,
    "artifact": 0.05,
    "uncertain": 0.05
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "The effect of mean adherence to a suppression-conditional recommended offensive mix on the probability of winning a playoff series. Adherence is defined as 1 minus the normalised l1 distance between the team's realised play-type distribution after a suppression trigger and the recommended distribution derived from all available pre-series data.",
    "unit": "One playoff series (the two teams are treated as a paired observation; the metric is the within-series difference in adherence, or simply an indicator of whether the more adherent team won).",
    "sample": "All available 54 playoff series across the 2022-23, 2023-24, 2024-25, and 2025-26 seasons (excluding series where either team has fewer than 50 suppression-triggered possessions in the pre-series window, to ensure a stable recommendation).",
    "power": "A one-sample exact binomial test (H0: p = 0.5) would require the true win rate of the more adherent team to be approximately 0.67 to achieve 80% power at two-sided alpha 0.05. This is well above the effect size implied by a +3.3 ORtg efficiency gain when translated through a logit win-probability model calibrated on playoff series. Power is therefore inadequate.",
    "controls": "In secondary analyses, series win could be regressed on the difference in mean adherence alongside controls: difference in regular-season net rating, difference in playoff seed, and an indicator for the team with home-court advantage. These controls partially address team-strength confounding.",
    "falsification": "Repeat the analysis after randomly permuting the recommended mix across teams within each season (500 permutations) to confirm that any observed association is not driven by structural features of the adherence metric. Additionally, test that adherence computed from the first two games of a series does not predict the remainder of the series, as a check on lookahead leakage.",
    "multiplicity": "If the recommendation is built from multiple play-type subsets (e.g., CUT-only, non-CUT, all), apply a Bonferroni-Holm correction across the primary binomial tests. Report all specifications, distinguishing confirmatory from exploratory.",
    "decision_rule": "The primary test is a two-sided binomal test of the proportion of series where the more adherent team wins. The null hypothesis is p = 0.5. The study would be considered supportive if the observed proportion is >0.5 with a two-sided p < 0.05 after multiplicity correction. Because the current sample size makes this unlikely to be satisfied even under a moderate true effect, we recommend not proceeding until a larger series pool (e.g., from additional seasons) is available.",
    "data_version": "NBA play-by-play 2022-23 through 2025-26 playoffs as documented in the data catalog, with play-type possessions derived from the graph database and suppression triggers defined per the standard suppression pipeline (POST_UP, PUTBACK, etc.). Pre-series recommendation windows use all prior regular-season and earlier-round games for the relevant season."
  }
}

